#include <stdio.h>
#include <stdlib.h>

struct Vector { int *data; size_t length; size_t capacity; };
int append(struct Vector *v, int value) {
 if (v->length == v->capacity) {
  if (v->capacity >= 2) { return 0; }
  int *next = realloc(v->data, 2 * sizeof *next);
  if (next == NULL) { return 0; }
  v->data = next; v->capacity = 2;
 }
 v->data[v->length++] = value;
 return 1;
}
int main(void) {
 struct Vector v = {.data = malloc(sizeof(int)), .length = 0, .capacity = 1};
 if (v.data == NULL) { return 1; }
 if (!append(&v, 3) || !append(&v, 7)) { free(v.data); return 1; }
 printf("%zu %d\n", v.length, v.data[1]);
 free(v.data);
}

